# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKÂNSAL BİLGİ TEKNOLOJİLERİNİN ÜÇ TEMEL BİLEŞENİ</text>\n  <rect x="22" y="42" width="208" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="126" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. KÜRESEL KONUMLANDIRMA</text>\n  <text x="126" y="82" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">(GPS / GNSS)</text>\n  <text x="34" y="106" font-size="11" fill="#1e3a8a">• Dünya yörüngesindeki uydulardan</text>\n  <text x="34" y="122" font-size="11" fill="#1e3a8a">gelen radyo sinyalleriyle çalışır.</text>\n  <text x="34" y="144" font-size="11" fill="#1e3a8a">• Enlem, boylam, yükselti ve</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">zamanı (mutlak konumu) belirler.</text>\n  <text x="34" y="182" font-size="11" font-weight="bold" fill="#1d4ed8">• Hassas konum için en az 4</text>\n  <text x="34" y="198" font-size="11" font-weight="bold" fill="#1d4ed8">uydudan sinyal alınmalıdır.</text>\n  <text x="34" y="220" font-size="10.5" fill="#3b82f6">GPS, GLONASS, Galileo, BeiDou</text>\n  <rect x="246" y="42" width="208" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. UZAKTAN ALGILAMA</text>\n  <text x="350" y="82" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">(UA / Remote Sensing)</text>\n  <text x="258" y="106" font-size="11" fill="#78350f">• Yeryüzü ile fiziksel temas</text>\n  <text x="258" y="122" font-size="11" fill="#78350f">kurmadan veri toplama teknolojisi.</text>\n  <text x="258" y="144" font-size="11" fill="#78350f">• Gözlem uyduları, uçaklar ve</text>\n  <text x="258" y="160" font-size="11" fill="#78350f">İHA\'lar üzerindeki algılayıcılarla</text>\n  <text x="258" y="176" font-size="11" fill="#78350f">(sensörlerle) görüntü alır.</text>\n  <text x="258" y="198" font-size="11" font-weight="bold" fill="#b45309">• Türkiye Gözlem Uyduları:</text>\n  <text x="258" y="216" font-size="10.5" fill="#92400e">RASAT, GÖKTÜRK-1, GÖKTÜRK-2, İMECE</text>\n  <rect x="470" y="42" width="208" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="574" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">3. COĞRAFİ BİLGİ SİSTEMLERİ</text>\n  <text x="574" y="82" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">(CBS / GIS)</text>\n  <text x="482" y="106" font-size="11" fill="#14532d">• Mekânsal verileri toplama,</text>\n  <text x="482" y="122" font-size="11" fill="#14532d">depolama, analiz etme ve</text>\n  <text x="482" y="138" font-size="11" fill="#14532d">görselleştirme (haritalama) sistemi.</text>\n  <text x="482" y="160" font-size="11" fill="#14532d">• Farklı veri katmanlarını (toprak,</text>\n  <text x="482" y="176" font-size="11" fill="#14532d">eğim, nüfus, ulaşım) çakıştırarak</text>\n  <text x="482" y="192" font-size="11" fill="#14532d">sorgulama ve karar verme sağlar.</text>\n  <text x="482" y="216" font-size="10.5" font-weight="bold" fill="#15803d">Donanım + Yazılım + Veri + İnsan + Yöntem</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CBS\'NİN 5 UNSURU VE KATMANLI VERİ MODELİ (VEKTÖREL &amp; RASTER)</text>\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">CBS (GIS) BİLEŞENLERİ</text>\n  <text x="40" y="92" font-size="12" fill="#581c87">1. Donanım: Bilgisayar, sunucu, tarayıcı, GPS alıcısı.</text>\n  <text x="40" y="116" font-size="12" fill="#581c87">2. Yazılım: Mekânsal analiz ve haritalama programları.</text>\n  <text x="40" y="140" font-size="12" font-weight="bold" fill="#7e22ce">3. Veri: CBS\'nin en temel ve maliyetli bileşeni!</text>\n  <text x="40" y="164" font-size="12" fill="#581c87">4. İnsan (Kullanıcı): Sistemi yöneten uzman personel.</text>\n  <text x="40" y="188" font-size="12" fill="#581c87">5. Yöntem: Kurumsal iş akışı ve analiz kuralları.</text>\n  <rect x="40" y="202" width="285" height="30" rx="6" fill="#f3e8ff"/>\n  <text x="182" y="221" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Öznitelik Tablosu: Haritadaki nesnelerin sözel/sayısal bilgisi.</text>\n  <rect x="355" y="42" width="320" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">MEKÂNSAL VERİ TÜRLERİ VE KATMANLAR</text>\n  <rect x="372" y="78" width="286" height="72" rx="6" fill="#ffffff" stroke="#fdba74"/>\n  <text x="382" y="98" font-size="12" font-weight="bold" fill="#c2410c">• Vektörel Veri (Koordinat Tabanlı):</text>\n  <text x="388" y="116" font-size="11" fill="#7c2d12">- Nokta: Kuyu, tepe, okul, deprem merkez üssü.</text>\n  <text x="388" y="131" font-size="11" fill="#7c2d12">- Çizgi: Akarsu, kara yolu, fay hattı, boru hattı.</text>\n  <text x="388" y="145" font-size="11" fill="#7c2d12">- Poligon (Alan): Göl, orman, il sınırı, tarım alanı.</text>\n  <rect x="372" y="158" width="286" height="72" rx="6" fill="#ffffff" stroke="#fdba74"/>\n  <text x="382" y="178" font-size="12" font-weight="bold" fill="#c2410c">• Raster (Hücresel / Piksel) Veri:</text>\n  <text x="388" y="196" font-size="11" fill="#7c2d12">- Eşit boyutlu kare hücrelerden (piksellerden) oluşur.</text>\n  <text x="388" y="213" font-size="11" fill="#7c2d12">- Uydu görüntüleri, hava fotoğrafları, sayısal yükselti.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİLEŞENLER ARASI ENTEGRASYON VE UYGULAMA ALANLARI</text>\n  <rect x="30" y="48" width="640" height="75" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="130" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">GPS / GNSS</text>\n  <text x="130" y="98" text-anchor="middle" font-size="11" fill="#164e63">(Hassas Konum Verisi)</text>\n  <text x="235" y="88" text-anchor="middle" font-size="18" font-weight="bold" fill="#0891b2">+</text>\n  <text x="345" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">UZAKTAN ALGILAMA</text>\n  <text x="345" y="98" text-anchor="middle" font-size="11" fill="#164e63">(Güncel Uydu Görüntüsü)</text>\n  <text x="455" y="88" text-anchor="middle" font-size="18" font-weight="bold" fill="#0891b2">→</text>\n  <text x="565" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">CBS (GIS) ANALİZİ</text>\n  <text x="565" y="98" text-anchor="middle" font-size="11" fill="#164e63">(Karar Destek ve Haritalama)</text>\n  <rect x="30" y="138" width="640" height="104" rx="10" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>\n  <text x="350" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">GÜNLÜK HAYAT VE PLANLAMADA KULLANIM ALANLARI</text>\n  <text x="50" y="184" font-size="11.5" fill="#334155">• Afet Yönetimi: Orman yangını, sel, heyelan ve deprem risk haritalarının oluşturulması, acil müdahale rotası.</text>\n  <text x="50" y="204" font-size="11.5" fill="#334155">• Çevre ve Tarım: Ürün rekolte tahmini, kuraklık ve buzulların erimesinin izlenmesi, ormansızlaşma takibi.</text>\n  <text x="50" y="224" font-size="11.5" fill="#334155">• Şehircilik ve Ulaşım: Navigasyon, akıllı ulaşım sistemleri, yeni hastane/okul/santral için en uygun yer seçimi.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
